-- Reproducible demo and test catalogue (60 books, fixed ids). Repeatable migration: runs only from the db/seed
-- Flyway location, which the dev and test profiles enable and the prod profile never does (see application*.yml).
-- Idempotent: never deletes rows and never resets live stock; a re-run only refreshes the author column.
-- No customers, passwords, orders or payment data are seeded. Covers are the generated SVGs in frontend/public/covers/.

-- Only the author is refreshed on re-run (AMD-003 regrouped the books under 12 writers); stock and prices are never touched.
ON CONFLICT (id) DO UPDATE SET author = EXCLUDED.author;

SELECT setval(pg_get_serial_sequence('book', 'id'), (SELECT MAX(id) FROM book));
